// Independent polynomial-basis field/group arithmetic and modular row replay.
// Never links the measured Rust library. No performance statistics computed here.
#include "native_helpers.hpp"
constexpr uint64_t R=8569786107849059ULL, LAMBDA=2998004823950457ULL;
P G{decimal("6614244651398184860292015"),decimal("8868260410029249391539529"),false};
uint64_t integer(const J&j){U v=num(j);require(v<=UINT64_MAX,"Integer overflow");return uint64_t(v);}
std::vector<uint64_t> row_values(const J&j){require(j.type=="array","Expected row array");std::vector<uint64_t> v;for(auto&x:j.array){auto n=integer(x);require(n<R,"Noncanonical scalar");v.push_back(n);}return v;}
struct Rows {
 size_t k,rank=0;std::vector<std::vector<uint64_t>> pivots;
 explicit Rows(size_t n):k(n),pivots(n){}
 bool insert(std::vector<uint64_t> v){require(v.size()==k+1,"Wrong row width");for(size_t c=0;c<k;c++){if(!v[c])continue;if(pivots[c].empty()){auto inv=power(v[c],R-2,R);for(auto&x:v)x=mm(x,inv,R);pivots[c]=v;rank++;return true;}auto factor=v[c];for(size_t j=c;j<=k;j++)v[j]=(v[j]+R-mm(factor,pivots[c][j],R))%R;}require(v[k]==0,"Inconsistent dependent row");return false;}
 std::vector<uint64_t> solve(){require(rank==k,"Incomplete rank");std::vector<uint64_t>x(k);for(size_t c=k;c-->0;){auto v=pivots[c][k];for(size_t j=c+1;j<k;j++)v=(v+R-mm(pivots[c][j],x[j],R))%R;x[c]=v;}return x;}
};
std::vector<J> lines(const files::path&p){auto text=bytes(p);require(!text.empty()&&text.back()=='\n',"Truncated JSONL");std::istringstream in(text);std::string line;std::vector<J> out;while(std::getline(in,line)){require(!line.empty(),"Empty record");Parser parser{line};auto v=parser.value();parser.ws();require(parser.i==line.size(),"Trailing JSON bytes");out.push_back(v);}return out;}
int main(int argc,char**argv){try{
 require(argc==6,"usage: verify_rank BASE.jsonl TRACE.jsonl ANSWERS.jsonl EXPECTED_RANK_SEED NEW_RECEIPT.json");
 auto base=read_json(argv[1]);check_modulus(base);require(integer(base.at("n"))==83&&integer(base.at("a"))==1&&integer(base.at("subgroup_order"))==R,"Wrong base curve");
 const auto&raw=base.at("factor_base_point_coordinates").array;const auto&labs=base.at("factor_base_point_labels").array;const auto&repraw=base.at("factor_base_representatives").array;
 size_t k=integer(base.at("orbit_columns"));require(k>0&&k<=1798&&repraw.size()==k&&raw.size()==166*k&&labs.size()==raw.size(),"Wrong base dimensions");
 std::vector<P> reps,points;std::vector<std::pair<size_t,uint64_t>> labels;std::set<U> distinct;
 require(on(G)&&mul(R,G).inf&&mul(LAMBDA,G)==tau(G),"Generator failure");
 for(size_t c=0;c<k;c++){auto rep=point(repraw[c]);require(on(rep)&&!rep.inf&&mul(R,rep).inf,"Base subgroup failure");require(distinct.insert(orbit_key(rep)).second,"Duplicate base orbit");reps.push_back(rep);P p=rep;uint64_t coeff=1;for(int n=0;n<83;n++){for(int sign=0;sign<2;sign++){size_t i=166*c+2*n+sign;auto stored=point(raw[i]);auto label=std::make_pair(c,sign?R-coeff:coeff);require(stored==(sign?neg(p):p),"Base point mismatch");require(integer(labs[i].at(0))==label.first&&integer(labs[i].at(1))==label.second,"Base label mismatch");points.push_back(stored);labels.push_back(label);}p=tau(p);coeff=mm(coeff,LAMBDA,R);}require(p==rep&&coeff==1,"Orbit closure failure");}
 auto records=lines(argv[2]);require(records.size()>=5,"Incomplete transcript");auto&h=records.front();require(h.at("kind").scalar=="n83_rank_header"&&h.at("schema").scalar=="n83-basis-rank/v1","Wrong trace schema");check_modulus(h);require(integer(h.at("n"))==83&&integer(h.at("a"))==1&&integer(h.at("r"))==R&&integer(h.at("columns"))==k&&point(h.at("generator"))==G&&h.at("base_hash").scalar==base.at("base_hash").scalar,"Header mismatch");
 uint64_t seed=integer(h.at("initial_rank_seed"));require(seed==std::stoull(argv[4]),"Unexpected rank seed");Rows rows(k);size_t i=1,attempts=0,relations=0,failures=0;uint64_t probes=0;
 auto witness=[&](const J&v,P target){auto&indices=v.at("point_indices").array;require(indices.size()==4,"Wrong witness size");P sum;for(auto&index:indices){auto j=integer(index);require(j<points.size(),"Witness index out of range");sum=add(sum,points[j]);}require(sum==target,"Four-point witness sum failure");auto&xs=v.at("x_codes").array;require(xs.size()==4,"Wrong x-code width");for(size_t t=0;t<4;t++)require(num(xs[t])==points[integer(indices[t])].x,"Witness x-code mismatch");auto&u=v.at("pinned_intermediates").array;require(u.size()==2,"Wrong intermediate count");auto p=add(points[integer(indices[0])],points[integer(indices[1])]);auto q=add(points[integer(indices[2])],points[integer(indices[3])]);require(!p.inf&&!q.inf&&p.x==num(u[0])&&q.x==num(u[1]),"Pinned intermediate mismatch");};
 while(i<records.size()&&records[i].at("kind").scalar=="n83_rank_attempt_start"){
  auto&s=records[i++];require(i<records.size(),"Unfinished attempt");auto&e=records[i++];require(e.at("kind").scalar=="n83_rank_attempt_end","Missing attempt end");attempts++;seed=seed*6364136223846793005ULL+1442695040888963407ULL;auto scalar=(seed>>11)%(R-1)+1;size_t col=0;while(col<k&&!rows.pivots[col].empty())col++;require(col<k,"Attempt after full rank");
  require(integer(s.at("attempt"))==attempts&&integer(e.at("attempt"))==attempts&&integer(s.at("rank_seed"))==seed,"Attempt ordering/seed mismatch");require(integer(s.at("scalar"))==scalar&&integer(e.at("scalar"))==scalar&&integer(s.at("column"))==col&&integer(e.at("column"))==col,"Anchor metadata mismatch");require(integer(s.at("rank_before"))==rows.rank&&integer(e.at("rank_before"))==rows.rank,"Rank-before mismatch");auto target=add(mul(scalar,G),neg(reps[col]));require(point(e.at("target"))==target,"Anchor group equality failure");
  bool gained=false;if(truth(e.at("found"))){relations++;witness(e,target);std::vector<uint64_t> row(k+1);for(auto&x:e.at("point_indices").array){auto label=labels[integer(x)];row[label.first]=(row[label.first]+label.second)%R;}row[col]=(row[col]+1)%R;row[k]=scalar;require(row_values(e.at("row"))==row,"Relation row mismatch");gained=rows.insert(row);}else{failures++;require(e.at("row").scalar=="null"&&e.at("point_indices").scalar=="null","Failed search carries row");}
  require(truth(e.at("gained"))==gained&&integer(e.at("rank_after"))==rows.rank,"Rank-after/gain mismatch");probes+=integer(e.at("probes"));for(auto&[key,v]:e.at("timing_ns").object)integer(v);
 }
 require(i+2==records.size(),"Missing final records or trailing records");auto&solution=records[i++];require(solution.at("kind").scalar=="n83_rank_solution"&&integer(solution.at("rank"))==k&&integer(solution.at("attempts"))==attempts&&integer(solution.at("relations"))==relations&&integer(solution.at("failures"))==failures&&integer(solution.at("probes"))==probes,"Solution counters mismatch");auto logs=rows.solve();require(row_values(solution.at("logs"))==logs,"Backsolve mismatch");for(size_t c=0;c<k;c++)require(mul(logs[c],G)==reps[c],"Representative log equality failure");require(records[i].at("kind").scalar=="n83_rank_trace_end","Missing trace footer");
 auto answers=lines(argv[3]);require(!answers.empty(),"No answers");for(size_t index=0;index<answers.size();index++){auto&v=answers[index];require(v.at("kind").scalar=="compact_orbit_dlp_target"&&integer(v.at("fixture_index"))==index&&truth(v.at("group_verified")),"Answer metadata failure");auto q=point(v.at("target"));require(on(q)&&!q.inf&&mul(R,q).inf&&point(v.at("published_q"))==q,"Answer Q validation failure");witness(v,q);auto d=integer(v.at("recovered_scalar"));require(d>0&&d<R&&mul(d,G)==q,"Answer scalar replay failure");uint64_t reconstructed=0;for(auto&x:v.at("point_indices").array){auto l=labels[integer(x)];reconstructed=(reconstructed+mm(l.second,logs[l.first],R))%R;}require(reconstructed==d,"Answer log reconstruction mismatch");}
 std::ostringstream out;out<<"{\"kind\":\"n83_basis_rank_verification\",\"status\":\"PASS\",\"columns\":"<<k<<",\"expected_rank_seed\":"<<argv[4]<<",\"attempts\":"<<attempts<<",\"relations\":"<<relations<<",\"answers\":"<<answers.size()<<",\"base_sha256\":"<<qstr(digest(argv[1]))<<",\"trace_sha256\":"<<qstr(digest(argv[2]))<<",\"answers_sha256\":"<<qstr(digest(argv[3]))<<",\"checker_source_sha256\":"<<qstr(digest(__FILE__))<<",\"checker_executable_sha256\":"<<qstr(digest(argv[0]))<<"}\n";create_new(argv[5],out.str());std::cout<<"PASS rank/log and answer transcript\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
